#!/usr/bin/env bash
# Ensure the example can compile on a fresh checkout.
#
# The example imports im_flutter_sdk/example/lib/env.dart, which is gitignored:
# locally it is generated by `make env-gettoken` from example/config.local.json;
# in CI no credentials exist, so this script only places the empty placeholder
# from example/templates/env.example.dart (chmod 600). It never creates
# example/config.local.json and never overwrites an existing env.dart.
#
# Safe to call repeatedly: keep an existing lib/env.dart untouched.
set -euo pipefail

repo_root="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
template="$repo_root/im_flutter_sdk/example/templates/env.example.dart"
target="$repo_root/im_flutter_sdk/example/lib/env.dart"

if [[ -f "$target" ]]; then
  echo "Keep: $target"
  exit 0
fi

mkdir -p "$(dirname "$target")"
cp "$template" "$target"
chmod 600 "$target"
echo "Created placeholder: $target (run 'make env-gettoken' for real credentials)"
